import type { ContentExpectation } from './content-expectation';

/**
 * What the server granted when it signed a link to upload a file straight to the storage: the
 * key, the size cap and the media types. Recorded on the server, on the aggregate that awaits
 * the file, by the command that signed the link; the command that confirms the upload reads it
 * back from there, never from what the client sends, so a client can neither choose the key it
 * confirms nor raise the cap.
 */
export interface PendingUpload extends ContentExpectation {
  /** The final key, generated by `FileKeys`; the file waits under its staged key. */
  readonly key: string;
  /** In bytes: what `FileStaging.confirm` accepts at most. */
  readonly maxBytes: number;
}
